def answer_squatting_question(image):
    image_patch = ImagePatch(image)
    girl_patches = image_patch.find("girl")

    if not girl_patches:
        return "No girl found in the image."

    squatting_girls = [patch for patch in girl_patches if patch.verify_property("girl", "squatting")]

    if not squatting_girls:
        return "No girl squating found in the image."

    skateboard_patches = []
    for girl_patch in squatting_girls:
        nearby_objects = girl_patch.llm_query("What objects are near the girl?", long_answer=False).split(", ")
        if "skateboard" in nearby_objects:
            skateboard_patches.append(girl_patch.crop(girl_patch.left - 50, girl_patch.lower - 50, girl_patch.right + 50, girl_patch.upper + 50))

    if not skateboard_patches:
        return "No skateboard found near the girl who is squatting."

    best_skateboard_patch = max(skateboard_patches, key=lambda patch: patch.compute_depth())
    return best_skateboard_patch.llm_query("Describe the skateboard.", long_answer=True)

